window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2023-tianjin"]=[{"id":"2023-tianjin-q01","paperId":"2023-tianjin","number":1,"type":"single","score":5,"lessonIds":["1.3"],"difficulty":"基础","hint":"先把全集中属于B的数划掉，再把剩下的数与A合在一起，重复成员只写一次。","legacy":false,"legacyReason":"","searchText":"已知集合 U=\\{1,2,3,4,5\\} ， A=\\{1,3\\} ， B=\\{1,2,4\\} ，则 \\complement_U B\\cup A= （ ） \\{1,3,5\\} \\{1,3\\} \\{1,2,4\\} \\{1,2,4,5\\}","questionHtml":"已知集合 <span class=\"gk-math\" data-tex=\"U=\\{1,2,3,4,5\\}\">U=\\{1,2,3,4,5\\}</span>，<span class=\"gk-math\" data-tex=\"A=\\{1,3\\}\">A=\\{1,3\\}</span>，<span class=\"gk-math\" data-tex=\"B=\\{1,2,4\\}\">B=\\{1,2,4\\}</span>，则 <span class=\"gk-math\" data-tex=\"\\complement_U B\\cup A=\">\\complement_U B\\cup A=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{1,3,5\\}\">\\{1,3,5\\}</span>","<span class=\"gk-math\" data-tex=\"\\{1,3\\}\">\\{1,3\\}</span>","<span class=\"gk-math\" data-tex=\"\\{1,2,4\\}\">\\{1,2,4\\}</span>","<span class=\"gk-math\" data-tex=\"\\{1,2,4,5\\}\">\\{1,2,4,5\\}</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\complement_U B=\\{3,5\\}\">\\complement_U B=\\{3,5\\}</span>， 故 <span class=\"gk-math\" data-tex=\"\\complement_U B\\cup A=\\{3,5\\}\\cup \\{1,3\\}=\\{1,3,5\\}\">\\complement_U B\\cup A=\\{3,5\\}\\cup \\{1,3\\}=\\{1,3,5\\}</span>. 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q02","paperId":"2023-tianjin","number":2,"type":"single","score":5,"lessonIds":["1.4","2.1"],"difficulty":"基础","hint":"把a²+b²=2ab改成(a−b)²=0，再检查a=b能否反推a²=b²，以及反方向有没有反例。","legacy":false,"legacyReason":"","searchText":"“ a^2=b^2 ”是“ a^2+b^2=2ab ”的（ ） 充分不必要条件 必要不充分条件 充分必要条件 既不充分又不必要条件","questionHtml":"“<span class=\"gk-math\" data-tex=\"a^2=b^2\">a^2=b^2</span>”是“<span class=\"gk-math\" data-tex=\"a^2+b^2=2ab\">a^2+b^2=2ab</span>”的（ ）","optionsHtml":["充分不必要条件","必要不充分条件","充分必要条件","既不充分又不必要条件"],"answerHtml":"B","answerKey":"B","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"a^2+b^2=2ab\">a^2+b^2=2ab</span> 得 <span class=\"gk-math\" data-tex=\"(a-b)^2=0\">(a-b)^2=0</span>， 故 <span class=\"gk-math\" data-tex=\"a=b\">a=b</span>，从而 <span class=\"gk-math\" data-tex=\"a^2=b^2\">a^2=b^2</span>，必要性成立. 但 <span class=\"gk-math\" data-tex=\"a^2=b^2\">a^2=b^2</span> 只说明 <span class=\"gk-math\" data-tex=\"a=\\pm b\">a=\\pm b</span>. 当 <span class=\"gk-math\" data-tex=\"a=-b\\ne 0\">a=-b\\ne 0</span> 时，<span class=\"gk-math\" data-tex=\"a^2+b^2\\ne 2ab\">a^2+b^2\\ne 2ab</span>，故充分性不成立. 所以为必要不充分条件. 故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q03","paperId":"2023-tianjin","number":3,"type":"single","score":5,"lessonIds":["4.2","3.3"],"difficulty":"基础","hint":"1.01大于1，指数越大结果越大；0.6的平方根仍小于1，用这两点排列三个数。","legacy":false,"legacyReason":"","searchText":"若 a=1.01^{0.5} ， b=1.01^{0.6} ， c=0.6^{0.5} ，则 a ， b ， c 的大小关系为（ ） a<b<c b<a<c c<b<a c<a<b","questionHtml":"若 <span class=\"gk-math\" data-tex=\"a=1.01^{0.5}\">a=1.01^{0.5}</span>，<span class=\"gk-math\" data-tex=\"b=1.01^{0.6}\">b=1.01^{0.6}</span>，<span class=\"gk-math\" data-tex=\"c=0.6^{0.5}\">c=0.6^{0.5}</span>，则 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span> 的大小关系为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"a&lt;b&lt;c\">a&lt;b&lt;c</span>","<span class=\"gk-math\" data-tex=\"b&lt;a&lt;c\">b&lt;a&lt;c</span>","<span class=\"gk-math\" data-tex=\"c&lt;b&lt;a\">c&lt;b&lt;a</span>","<span class=\"gk-math\" data-tex=\"c&lt;a&lt;b\">c&lt;a&lt;b</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"1.01&gt;1\">1.01&gt;1</span>，故指数函数 <span class=\"gk-math\" data-tex=\"1.01^x\">1.01^x</span> 单调递增，所以 <span class=\"gk-math\" data-tex=\"b=1.01^{0.6}&gt;a=1.01^{0.5}\">b=1.01^{0.6}&gt;a=1.01^{0.5}</span>. 又因为 <span class=\"gk-math\" data-tex=\"0.6&lt;1.01\">0.6&lt;1.01</span>，且 <span class=\"gk-math\" data-tex=\"x^{0.5}\">x^{0.5}</span> 在 <span class=\"gk-math\" data-tex=\"[0,+\\infty)\">[0,+\\infty)</span> 上单调递增，所以 <span class=\"gk-math\" data-tex=\"c=0.6^{0.5}&lt;1.01^{0.5}=a\">c=0.6^{0.5}&lt;1.01^{0.5}=a</span>. 故 <span class=\"gk-math\" data-tex=\"b&gt;a&gt;c\">b&gt;a&gt;c</span>. 故选 D.","sourceNote":"题干和题号统一采用完整试卷整理本；与考后回忆版的选项顺序不同。","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q04","paperId":"2023-tianjin","number":4,"type":"single","score":5,"lessonIds":["3.2","5.4"],"difficulty":"基础","hint":"先看图象是否关于y轴对称，再看它是否出现负值。奇偶性和正负就能排除大部分选项。","legacy":false,"legacyReason":"","searchText":"函数 f(x) 的图象如下图所示，则 f(x) 的解析式可能为（ ） \\dfrac{5(\\e^x-\\e^{-x})}{x^2+2} \\dfrac{5\\sin x}{x^2+1} \\dfrac{5(\\e^x+\\e^{-x})}{x^2+2} \\dfrac{5\\cos x}{x^2+1}","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的图象如下图所示，则 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的解析式可能为（ ）<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,600px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q4_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q4_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"584\" height=\"376\" style=\"aspect-ratio:584/376;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{5(\\e^x-\\e^{-x})}{x^2+2}\">\\dfrac{5(\\e^x-\\e^{-x})}{x^2+2}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{5\\sin x}{x^2+1}\">\\dfrac{5\\sin x}{x^2+1}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{5(\\e^x+\\e^{-x})}{x^2+2}\">\\dfrac{5(\\e^x+\\e^{-x})}{x^2+2}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{5\\cos x}{x^2+1}\">\\dfrac{5\\cos x}{x^2+1}</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"由图分析可知：函数图象关于 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴对称，其为偶函数，且 <span class=\"gk-math\" data-tex=\"f(-2)=f(2)&lt;0\">f(-2)=f(2)&lt;0</span>. 由 <span class=\"gk-math\" data-tex=\"\\frac{5\\sin(-x)}{(-x)^2+1}=-\\frac{5\\sin x}{x^2+1}\">\\frac{5\\sin(-x)}{(-x)^2+1}=-\\frac{5\\sin x}{x^2+1}</span> 且定义域为 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span>，即 B 中函数为奇函数，排除. 当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时，<span class=\"gk-math\" data-tex=\"\\frac{5(\\e^x-\\e^{-x})}{x^2+2}&gt;0\">\\frac{5(\\e^x-\\e^{-x})}{x^2+2}&gt;0</span>，<span class=\"gk-math\" data-tex=\"\\frac{5(\\e^x+\\e^{-x})}{x^2+2}&gt;0\">\\frac{5(\\e^x+\\e^{-x})}{x^2+2}&gt;0</span>，即 A，C 中函数在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上函数值为正，排除. 故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q05","paperId":"2023-tianjin","number":5,"type":"single","score":5,"lessonIds":["e2-4.3","e2-4.1"],"difficulty":"进阶","hint":"先从a₁=2算S₁，再由a₂=2S₁+2算出下一项，重复这一步直到a₄。","legacy":false,"legacyReason":"","searchText":"已知数列 \\{a_n\\} 的前 n 项和为 S_n . 若 a_1=2 ， a_{n+1}=2S_n+2 （ n\\in\\N^* ），则 a_4= （ ） 16 32 54 162","questionHtml":"已知数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和为 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span>. 若 <span class=\"gk-math\" data-tex=\"a_1=2\">a_1=2</span>，<span class=\"gk-math\" data-tex=\"a_{n+1}=2S_n+2\">a_{n+1}=2S_n+2</span>（<span class=\"gk-math\" data-tex=\"n\\in\\N^*\">n\\in\\N^*</span>），则 <span class=\"gk-math\" data-tex=\"a_4=\">a_4=</span>（ ）","optionsHtml":["16","32","54","162"],"answerHtml":"C","answerKey":"C","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"a_1=2\">a_1=2</span>，得 <span class=\"gk-math\" data-tex=\"S_1=2\">S_1=2</span>，所以 <span class=\"gk-math\" data-tex=\"a_2=2S_1+2=6\">a_2=2S_1+2=6</span>. 于是 <span class=\"gk-math\" data-tex=\"S_2=2+6=8\">S_2=2+6=8</span>，<span class=\"gk-math\" data-tex=\"a_3=2S_2+2=18\">a_3=2S_2+2=18</span>；接着 <span class=\"gk-math\" data-tex=\"S_3=2+6+18=26\">S_3=2+6+18=26</span>，<span class=\"gk-math\" data-tex=\"a_4=2S_3+2=54\">a_4=2S_3+2=54</span>，故选 C.","sourceNote":"采用完整试卷整理本的第5题；早期回忆版将数列题排为第6题。","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q06","paperId":"2023-tianjin","number":6,"type":"single","score":5,"lessonIds":["5.4","5.6"],"difficulty":"基础","hint":"4是一个周期，先排除周期不合适的函数；再把x=2代入，看这里是不是最高点或最低点。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x) 的一条对称轴为直线 x=2 ，一个周期为 4，则 f(x) 的解析式可能为（ ） \\sin \\left( \\dfrac{\\pi}{2}x \\right) \\cos \\left( \\dfrac{\\pi}{2}x \\right) \\sin \\left( \\dfrac{\\pi}{4}x \\right) \\cos \\left( \\dfrac{\\pi}{4}x \\right)","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的一条对称轴为直线 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span>，一个周期为 4，则 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的解析式可能为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\sin \\left( \\dfrac{\\pi}{2}x \\right)\">\\sin \\left( \\dfrac{\\pi}{2}x \\right)</span>","<span class=\"gk-math\" data-tex=\"\\cos \\left( \\dfrac{\\pi}{2}x \\right)\">\\cos \\left( \\dfrac{\\pi}{2}x \\right)</span>","<span class=\"gk-math\" data-tex=\"\\sin \\left( \\dfrac{\\pi}{4}x \\right)\">\\sin \\left( \\dfrac{\\pi}{4}x \\right)</span>","<span class=\"gk-math\" data-tex=\"\\cos \\left( \\dfrac{\\pi}{4}x \\right)\">\\cos \\left( \\dfrac{\\pi}{4}x \\right)</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"A，B 两式的周期均为 <span class=\"gk-math\" data-tex=\"\\frac{2\\pi}{\\frac{\\pi}{2}}=4\">\\frac{2\\pi}{\\frac{\\pi}{2}}=4</span>，C，D 两式的周期均为 8，先排除 C，D. 再检验 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span>：<span class=\"gk-math\" data-tex=\"\\sin \\left( \\frac{\\pi}{2}\\times 2 \\right)=\\sin \\pi=0\">\\sin \\left( \\frac{\\pi}{2}\\times 2 \\right)=\\sin \\pi=0</span>，所以 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 是 <span class=\"gk-math\" data-tex=\"\\sin \\left( \\frac{\\pi}{2}x \\right)\">\\sin \\left( \\frac{\\pi}{2}x \\right)</span> 图象的对称中心，不是对称轴. 而 <span class=\"gk-math\" data-tex=\"\\cos \\left( \\frac{\\pi}{2}\\times 2 \\right)=\\cos \\pi=-1\">\\cos \\left( \\frac{\\pi}{2}\\times 2 \\right)=\\cos \\pi=-1</span>，故 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 是 <span class=\"gk-math\" data-tex=\"\\cos \\left( \\frac{\\pi}{2}x \\right)\">\\cos \\left( \\frac{\\pi}{2}x \\right)</span> 的一条对称轴. 故选 B.","sourceNote":"采用完整试卷整理本的第6题；早期回忆版将三角函数题排为第5题。","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q07","paperId":"2023-tianjin","number":7,"type":"single","score":5,"lessonIds":["e3-8.1","e3-8.2"],"difficulty":"基础","hint":"相关系数大于0，先判断正相关。再把花萼长度x=7代入回归方程，看看预测的平均花瓣长度。","legacy":false,"legacyReason":"","searchText":"鸢是鹰科的一种鸟，《诗经·大雅·旱麓》曰“鸢飞戾天，鱼跃于渊”. 鸢尾花因花瓣形如鸢尾而得名（图1），寓意鹏程万里、前途无量. 通过随机抽样，收集了若干朵某品种鸢尾花的花萼长度和花瓣长度（单位： \\mathrm{cm} ），绘制对应散点图（图2）如下，计算得样本相关系数为 0.8642 ，利用最小二乘法求得相应的经验回归方程为 \\hat y=0.7501x+0.6105 . 根据以上信息，如下判断正确的为（ ） 花萼长度与花瓣长度不存在相关关系 花萼长度与花瓣长度负相关 花萼长度为 7\\,\\mathrm{cm} 的该品种鸢尾花的花瓣长度的平均值约为 5.8612\\,\\mathrm{cm} 若选取其他品种鸢尾花进行抽样，所得花萼长度与花瓣长度的样本相关系数一定为 0.8642","questionHtml":"鸢是鹰科的一种鸟，《诗经·大雅·旱麓》曰“鸢飞戾天，鱼跃于渊”. 鸢尾花因花瓣形如鸢尾而得名（图1），寓意鹏程万里、前途无量. 通过随机抽样，收集了若干朵某品种鸢尾花的花萼长度和花瓣长度（单位：<span class=\"gk-math\" data-tex=\"\\mathrm{cm}\">\\mathrm{cm}</span>），绘制对应散点图（图2）如下，计算得样本相关系数为 <span class=\"gk-math\" data-tex=\"0.8642\">0.8642</span>，利用最小二乘法求得相应的经验回归方程为 <span class=\"gk-math\" data-tex=\"\\hat y=0.7501x+0.6105\">\\hat y=0.7501x+0.6105</span>. 根据以上信息，如下判断正确的为（ ） <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,459px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q7_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q7_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"443\" height=\"530\" style=\"aspect-ratio:443/530;width:100%\" loading=\"lazy\"></button></figure> <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,801px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q7_fig2.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q7_fig2.webp\" alt=\"高考题图，点击可放大\" width=\"785\" height=\"542\" style=\"aspect-ratio:785/542;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["花萼长度与花瓣长度不存在相关关系","花萼长度与花瓣长度负相关","花萼长度为 <span class=\"gk-math\" data-tex=\"7\\,\\mathrm{cm}\">7\\,\\mathrm{cm}</span> 的该品种鸢尾花的花瓣长度的平均值约为 <span class=\"gk-math\" data-tex=\"5.8612\\,\\mathrm{cm}\">5.8612\\,\\mathrm{cm}</span>","若选取其他品种鸢尾花进行抽样，所得花萼长度与花瓣长度的样本相关系数一定为 <span class=\"gk-math\" data-tex=\"0.8642\">0.8642</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"样本相关系数 <span class=\"gk-math\" data-tex=\"r=0.8642&gt;0\">r=0.8642&gt;0</span>，说明花萼长度与花瓣长度呈正相关，A、B 错误. 当 <span class=\"gk-math\" data-tex=\"x=7\">x=7</span> 时，回归方程给出 <span class=\"gk-math\" data-tex=\"\\hat y=0.7501\\times7+0.6105=5.8612\">\\hat y=0.7501\\times7+0.6105=5.8612</span>，这是平均水平的估计，因此 C 正确. 换成其他样本或品种后，相关系数不一定相同，D 错误. 故选 C.","sourceNote":"按完整试卷整理本补齐鸢尾花背景、相关系数0.8642和经验回归方程；早期回忆版该题不完整。","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q08","paperId":"2023-tianjin","number":8,"type":"single","score":5,"lessonIds":["8.3"],"difficulty":"进阶","hint":"先比较同一平面内三角形PMN与PBC的面积。两个分点比例要相乘，再利用共同的高。","legacy":false,"legacyReason":"","searchText":"在三棱锥 P-ABC 中，点 M ， N 分别在棱 PB 和 PC 上，且 PM=\\dfrac13PB ， PN=\\dfrac23PC ，则三棱锥 P-AMN 和三棱锥 P-ABC 的体积之比为（ ） \\dfrac19 \\dfrac29 \\dfrac13 \\dfrac49","questionHtml":"在三棱锥 <span class=\"gk-math\" data-tex=\"P-ABC\">P-ABC</span> 中，点 <span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span> 分别在棱 <span class=\"gk-math\" data-tex=\"PB\">PB</span> 和 <span class=\"gk-math\" data-tex=\"PC\">PC</span> 上，且 <span class=\"gk-math\" data-tex=\"PM=\\dfrac13PB\">PM=\\dfrac13PB</span>，<span class=\"gk-math\" data-tex=\"PN=\\dfrac23PC\">PN=\\dfrac23PC</span>，则三棱锥 <span class=\"gk-math\" data-tex=\"P-AMN\">P-AMN</span> 和三棱锥 <span class=\"gk-math\" data-tex=\"P-ABC\">P-ABC</span> 的体积之比为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac19\">\\dfrac19</span>","<span class=\"gk-math\" data-tex=\"\\dfrac29\">\\dfrac29</span>","<span class=\"gk-math\" data-tex=\"\\dfrac13\">\\dfrac13</span>","<span class=\"gk-math\" data-tex=\"\\dfrac49\">\\dfrac49</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"取 <span class=\"gk-math\" data-tex=\"\\triangle PMN\">\\triangle PMN</span> 和 <span class=\"gk-math\" data-tex=\"\\triangle PBC\">\\triangle PBC</span> 为底面时，两三棱锥顶点都是 <span class=\"gk-math\" data-tex=\"A\">A</span>，高相同. 两底面夹角都是 <span class=\"gk-math\" data-tex=\"\\angle BPC\">\\angle BPC</span>，所以面积比为 <span class=\"gk-math\" data-tex=\"\\dfrac{PM\\cdot PN}{PB\\cdot PC}=\\dfrac13\\times\\dfrac23=\\dfrac29\">\\dfrac{PM\\cdot PN}{PB\\cdot PC}=\\dfrac13\\times\\dfrac23=\\dfrac29</span>. 体积比也为 <span class=\"gk-math\" data-tex=\"\\dfrac29\">\\dfrac29</span>，故选 B.","sourceNote":"按完整试卷整理本统一M在PB、N在PC；早期回忆版交换了两棱标记。","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q09","paperId":"2023-tianjin","number":9,"type":"single","score":5,"lessonIds":["e1-3.2","e1-2.3"],"difficulty":"进阶","hint":"先用右焦点到渐近线的距离求b，再把垂足P的坐标代入PF₁的斜率条件。","legacy":false,"legacyReason":"","searchText":"双曲线 \\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1 （ a>0 ， b>0 ） 的左，右焦点分别为 F_1 ， F_2 . 过 F_2 作其中一条渐近线的垂线，垂足为 P . 已知 PF_2=2 ，直线 PF_1 的斜率为 \\dfrac{\\sqrt{2}}{4} ，则双曲线的方程为（ ） \\dfrac{x^2}{8}-\\dfrac{y^2}{4}=1 \\dfrac{x^2}{4}-\\dfrac{y^2}{8}=1 \\dfrac{x^2}{4}-\\dfrac{y^2}{2}=1 \\dfrac{x^2}{2}-\\dfrac{y^2}{4}=1","questionHtml":"双曲线 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1\">\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>） 的左，右焦点分别为 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span>，<span class=\"gk-math\" data-tex=\"F_2\">F_2</span>. 过 <span class=\"gk-math\" data-tex=\"F_2\">F_2</span> 作其中一条渐近线的垂线，垂足为 <span class=\"gk-math\" data-tex=\"P\">P</span>. 已知 <span class=\"gk-math\" data-tex=\"PF_2=2\">PF_2=2</span>，直线 <span class=\"gk-math\" data-tex=\"PF_1\">PF_1</span> 的斜率为 <span class=\"gk-math\" data-tex=\"\\dfrac{\\sqrt{2}}{4}\">\\dfrac{\\sqrt{2}}{4}</span>，则双曲线的方程为（ ）<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,360px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q9_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q9_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"344\" height=\"344\" style=\"aspect-ratio:344/344;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{8}-\\dfrac{y^2}{4}=1\">\\dfrac{x^2}{8}-\\dfrac{y^2}{4}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{4}-\\dfrac{y^2}{8}=1\">\\dfrac{x^2}{4}-\\dfrac{y^2}{8}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{4}-\\dfrac{y^2}{2}=1\">\\dfrac{x^2}{4}-\\dfrac{y^2}{2}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{2}-\\dfrac{y^2}{4}=1\">\\dfrac{x^2}{2}-\\dfrac{y^2}{4}=1</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"设右焦点 <span class=\"gk-math\" data-tex=\"F_2(c,0)\">F_2(c,0)</span>，取渐近线 <span class=\"gk-math\" data-tex=\"y=\\frac{b}{a}x\">y=\\frac{b}{a}x</span>. 则点到直线距离公式给出 <span class=\"gk-math\" data-tex=\"PF_2=\\frac{bc}{\\sqrt{a^2+b^2}}=2\">PF_2=\\frac{bc}{\\sqrt{a^2+b^2}}=2</span>. 又双曲线满足 <span class=\"gk-math\" data-tex=\"c^2=a^2+b^2\">c^2=a^2+b^2</span>，故 <span class=\"gk-math\" data-tex=\"PF_2=\\frac{bc}{c}=b=2\">PF_2=\\frac{bc}{c}=b=2</span>. 再由图可知 <span class=\"gk-math\" data-tex=\"\\tan \\angle POF_2=\\frac{b}{a}\">\\tan \\angle POF_2=\\frac{b}{a}</span>，从而 <span class=\"gk-math\" data-tex=\"OP=a\">OP=a</span>. 设 <span class=\"gk-math\" data-tex=\"P\\left( \\frac{a^2}{c},\\frac{ab}{c} \\right)\">P\\left( \\frac{a^2}{c},\\frac{ab}{c} \\right)</span>，由 <span class=\"gk-math\" data-tex=\"k_{PF_1}=\\frac{\\frac{ab}{c}}{\\frac{a^2}{c}+c}\">k_{PF_1}=\\frac{\\frac{ab}{c}}{\\frac{a^2}{c}+c}</span> 并代入 <span class=\"gk-math\" data-tex=\"b=2\">b=2</span>，<span class=\"gk-math\" data-tex=\"c^2=a^2+4\">c^2=a^2+4</span>，得 <span class=\"gk-math\" data-tex=\"\\frac{a}{a^2+2}=\\frac{\\sqrt2}{4}\">\\frac{a}{a^2+2}=\\frac{\\sqrt2}{4}</span>. 解得 <span class=\"gk-math\" data-tex=\"a=\\sqrt2\">a=\\sqrt2</span>. 故所求双曲线方程为 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{2}-\\frac{y^2}{4}=1\">\\frac{x^2}{2}-\\frac{y^2}{4}=1</span>. 故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q10","paperId":"2023-tianjin","number":10,"type":"fill","score":5,"lessonIds":["7.2"],"difficulty":"基础","hint":"分子分母同时乘2−3i，先算分母的平方和，再展开分子。","legacy":false,"legacyReason":"","searchText":"已知 \\i 是虚数单位，化简 \\frac{5+14\\i}{2+3\\i} 的结果为 ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"\\i\">\\i</span> 是虚数单位，化简 <span class=\"gk-math\" data-tex=\"\\frac{5+14\\i}{2+3\\i}\">\\frac{5+14\\i}{2+3\\i}</span> 的结果为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"4+\\i\">4+\\i</span>","answerKey":"","solutionHtml":"有 <span class=\"gk-math\" data-tex=\"\\frac{5+14\\i}{2+3\\i}=\\frac{(5+14\\i)(2-3\\i)}{(2+3\\i)(2-3\\i)}=\\frac{52+13\\i}{13}=4+\\i\">\\frac{5+14\\i}{2+3\\i}=\\frac{(5+14\\i)(2-3\\i)}{(2+3\\i)(2-3\\i)}=\\frac{52+13\\i}{13}=4+\\i</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q11","paperId":"2023-tianjin","number":11,"type":"fill","score":5,"lessonIds":["e3-6.3"],"difficulty":"基础","hint":"写第k+1项时，x的总指数是3(6−k)−k。令它等于2，找出需要的那一项。","legacy":false,"legacyReason":"","searchText":"在 \\left( 2x^3-\\frac{1}{x} \\right)^6 的展开式中， x^2 项的系数为 ________ . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\left( 2x^3-\\frac{1}{x} \\right)^6\">\\left( 2x^3-\\frac{1}{x} \\right)^6</span> 的展开式中，<span class=\"gk-math\" data-tex=\"x^2\">x^2</span> 项的系数为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"60","answerKey":"","solutionHtml":"展开式通项为 <span class=\"gk-math\" data-tex=\"T_{k+1}=\\mathrm{C}_6^k (2x^3)^{6-k}\\left(-\\frac{1}{x}\\right)^k=(-1)^k 2^{6-k}\\mathrm{C}_6^k x^{18-4k}\">T_{k+1}=\\mathrm{C}_6^k (2x^3)^{6-k}\\left(-\\frac{1}{x}\\right)^k=(-1)^k 2^{6-k}\\mathrm{C}_6^k x^{18-4k}</span>. 令 <span class=\"gk-math\" data-tex=\"18-4k=2\">18-4k=2</span>，得 <span class=\"gk-math\" data-tex=\"k=4\">k=4</span>. 故系数为 <span class=\"gk-math\" data-tex=\"(-1)^4 2^2 \\mathrm{C}_6^4=4\\times 15=60\">(-1)^4 2^2 \\mathrm{C}_6^4=4\\times 15=60</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q12","paperId":"2023-tianjin","number":12,"type":"fill","score":5,"lessonIds":["e1-2.5","e1-3.3","e1-2.3"],"difficulty":"进阶","hint":"过原点的直线设为y=kx。相切表示圆心到直线的距离等于半径，先求k²。","legacy":false,"legacyReason":"","searchText":"过原点的一条直线与圆 C:(x+2)^2+y^2=3 相切，交曲线 y^2=2px （ p>0 ） 于点 P ，若 |OP|=8 ，则 p 的值为 ________ . ","questionHtml":"过原点的一条直线与圆 <span class=\"gk-math\" data-tex=\"C:(x+2)^2+y^2=3\">C:(x+2)^2+y^2=3</span> 相切，交曲线 <span class=\"gk-math\" data-tex=\"y^2=2px\">y^2=2px</span>（<span class=\"gk-math\" data-tex=\"p&gt;0\">p&gt;0</span>） 于点 <span class=\"gk-math\" data-tex=\"P\">P</span>，若 <span class=\"gk-math\" data-tex=\"|OP|=8\">|OP|=8</span>，则 <span class=\"gk-math\" data-tex=\"p\">p</span> 的值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"6","answerKey":"","solutionHtml":"设切线方程为 <span class=\"gk-math\" data-tex=\"y=kx\">y=kx</span>（<span class=\"gk-math\" data-tex=\"k&gt;0\">k&gt;0</span>）. 直线与圆相切，所以圆心 <span class=\"gk-math\" data-tex=\"(-2,0)\">(-2,0)</span> 到直线 <span class=\"gk-math\" data-tex=\"y=kx\">y=kx</span> 的距离为 <span class=\"gk-math\" data-tex=\"\\sqrt3\">\\sqrt3</span>，即 <span class=\"gk-math\" data-tex=\"\\frac{2|k|}{\\sqrt{1+k^2}}=\\sqrt3\">\\frac{2|k|}{\\sqrt{1+k^2}}=\\sqrt3</span>. 解得 <span class=\"gk-math\" data-tex=\"k=\\sqrt3\">k=\\sqrt3</span>. 联立 <span class=\"gk-math\" data-tex=\"\\begin{cases}\ny=\\sqrt3 x,\\\\\ny^2=2px,\n\\end{cases}\">\\begin{cases}\ny=\\sqrt3 x,\\\\\ny^2=2px,\n\\end{cases}</span> 得除原点外 <span class=\"gk-math\" data-tex=\"x=\\frac{2p}{3}\">x=\\frac{2p}{3}</span>，<span class=\"gk-math\" data-tex=\"y=\\frac{2\\sqrt3 p}{3}\">y=\\frac{2\\sqrt3 p}{3}</span>. 故 <span class=\"gk-math\" data-tex=\"|OP|=\\sqrt{\\left( \\frac{2p}{3} \\right)^2+\\left( \\frac{2\\sqrt3 p}{3} \\right)^2}=\\frac{4p}{3}\">|OP|=\\sqrt{\\left( \\frac{2p}{3} \\right)^2+\\left( \\frac{2\\sqrt3 p}{3} \\right)^2}=\\frac{4p}{3}</span>. 由 <span class=\"gk-math\" data-tex=\"|OP|=8\">|OP|=8</span> 得 <span class=\"gk-math\" data-tex=\"\\frac{4p}{3}=8\">\\frac{4p}{3}=8</span>，解得 <span class=\"gk-math\" data-tex=\"p=6\">p=6</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q13","paperId":"2023-tianjin","number":13,"type":"fill","score":5,"lessonIds":["10.2","e3-7.1"],"difficulty":"基础","hint":"三个盒子各摸一次，第一空把三个黑球概率相乘；混在一起后要按5:4:6加权，不能直接平均。","legacy":false,"legacyReason":"","searchText":"甲，乙，丙三个盒子中装有一定数量的黑球和白球，其总数之比为 5:4:6 . 这三个盒子中黑球占总数的比例分别为 40\\% ， 25\\% ， 50\\% . 现从三个盒子中各取一个球，取到的三个球都是黑球的概率为 ________ ；将三个盒子混合后任取一个球，是白球的概率为 ________ . ","questionHtml":"甲，乙，丙三个盒子中装有一定数量的黑球和白球，其总数之比为 <span class=\"gk-math\" data-tex=\"5:4:6\">5:4:6</span>. 这三个盒子中黑球占总数的比例分别为 <span class=\"gk-math\" data-tex=\"40\\%\">40\\%</span>，<span class=\"gk-math\" data-tex=\"25\\%\">25\\%</span>，<span class=\"gk-math\" data-tex=\"50\\%\">50\\%</span>. 现从三个盒子中各取一个球，取到的三个球都是黑球的概率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>；将三个盒子混合后任取一个球，是白球的概率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"0.05；<span class=\"gk-math\" data-tex=\"\\dfrac{3}{5}\">\\dfrac{3}{5}</span>","answerKey":"","solutionHtml":"从三个盒子中各取一个球，均为黑球的概率为 <span class=\"gk-math\" data-tex=\"\\;0.4\\times 0.25\\times 0.5=0.05\">\\;0.4\\times 0.25\\times 0.5=0.05</span>.<br><br>设三个盒子球数分别为 <span class=\"gk-math\" data-tex=\"5n\">5n</span>，<span class=\"gk-math\" data-tex=\"4n\">4n</span>，<span class=\"gk-math\" data-tex=\"6n\">6n</span>. 则黑球数分别为 <span class=\"gk-math\" data-tex=\"2n\">2n</span>，<span class=\"gk-math\" data-tex=\"n\">n</span>，<span class=\"gk-math\" data-tex=\"3n\">3n</span>， 白球总数为 <span class=\"gk-math\" data-tex=\"15n-(2n+n+3n)=9n\">15n-(2n+n+3n)=9n</span>. 故混合后任取一球为白球的概率为 <span class=\"gk-math\" data-tex=\"\\frac{9n}{15n}=\\frac{3}{5}\">\\frac{9n}{15n}=\\frac{3}{5}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q14","paperId":"2023-tianjin","number":14,"type":"fill","score":5,"lessonIds":["6.2","6.4","2.2"],"difficulty":"进阶","hint":"先用中点公式表示AE和AF。把数量积改成AB、AC的长度，再用BC=1限制这两条边。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中， \\angle A=60^\\circ ， BC=1 ，点 D 为 AB 的中点，点 E 为 CD 的中点. 若设 \\overrightarrow{AB}=\\bs{a} ， \\overrightarrow{AC}=\\bs{b} ，则 \\overrightarrow{AE} 可用 \\bs{a} ， \\bs{b} 表示为 ________ ；若 \\overrightarrow{BF}=\\dfrac{1}{3}\\overrightarrow{BC} ，则 \\overrightarrow{AE}\\cdot \\overrightarrow{AF} 的最大值为 ________ . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，<span class=\"gk-math\" data-tex=\"\\angle A=60^\\circ\">\\angle A=60^\\circ</span>，<span class=\"gk-math\" data-tex=\"BC=1\">BC=1</span>，点 <span class=\"gk-math\" data-tex=\"D\">D</span> 为 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的中点，点 <span class=\"gk-math\" data-tex=\"E\">E</span> 为 <span class=\"gk-math\" data-tex=\"CD\">CD</span> 的中点. 若设 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AB}=\\bs{a}\">\\overrightarrow{AB}=\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{AC}=\\bs{b}\">\\overrightarrow{AC}=\\bs{b}</span>，则 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AE}\">\\overrightarrow{AE}</span> 可用 <span class=\"gk-math\" data-tex=\"\\bs{a}\">\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}\">\\bs{b}</span> 表示为<span class=\"gk-blank\" aria-label=\"填空\">________</span>；若 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BF}=\\dfrac{1}{3}\\overrightarrow{BC}\">\\overrightarrow{BF}=\\dfrac{1}{3}\\overrightarrow{BC}</span>，则 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AE}\\cdot \\overrightarrow{AF}\">\\overrightarrow{AE}\\cdot \\overrightarrow{AF}</span> 的最大值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\dfrac{1}{4}\\bs{a}+\\dfrac{1}{2}\\bs{b}\">\\dfrac{1}{4}\\bs{a}+\\dfrac{1}{2}\\bs{b}</span>；<span class=\"gk-math\" data-tex=\"\\dfrac{13}{24}\">\\dfrac{13}{24}</span>","answerKey":"","solutionHtml":"<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,383px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q14_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q14_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"367\" height=\"282\" style=\"aspect-ratio:367/282;width:100%\" loading=\"lazy\"></button></figure> 空 1：因为 <span class=\"gk-math\" data-tex=\"D\">D</span> 为 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的中点，<span class=\"gk-math\" data-tex=\"E\">E</span> 为 <span class=\"gk-math\" data-tex=\"CD\">CD</span> 的中点，所以 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AD}=\\frac{1}{2}\\bs{a}\">\\overrightarrow{AD}=\\frac{1}{2}\\bs{a}</span>，且 <span class=\"gk-math\" data-tex=\"2\\overrightarrow{AE}=\\overrightarrow{AD}+\\overrightarrow{AC}\">2\\overrightarrow{AE}=\\overrightarrow{AD}+\\overrightarrow{AC}</span>. 故 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AE}=\\frac{1}{4}\\bs{a}+\\frac{1}{2}\\bs{b}\">\\overrightarrow{AE}=\\frac{1}{4}\\bs{a}+\\frac{1}{2}\\bs{b}</span>.<br><br>空 2：由 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BF}=\\dfrac{1}{3}\\overrightarrow{BC}\">\\overrightarrow{BF}=\\dfrac{1}{3}\\overrightarrow{BC}</span> 得 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AF}=\\frac{2}{3}\\bs{a}+\\frac{1}{3}\\bs{b}\">\\overrightarrow{AF}=\\frac{2}{3}\\bs{a}+\\frac{1}{3}\\bs{b}</span>. 于是 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AE}\\cdot \\overrightarrow{AF}=\\left( \\frac{1}{4}\\bs{a}+\\frac{1}{2}\\bs{b} \\right)\\cdot \\left( \\frac{2}{3}\\bs{a}+\\frac{1}{3}\\bs{b} \\right)=\\frac{1}{12}\\left( 2|\\bs{a}|^2+5\\bs{a}\\cdot\\bs{b}+2|\\bs{b}|^2 \\right)\">\\overrightarrow{AE}\\cdot \\overrightarrow{AF}=\\left( \\frac{1}{4}\\bs{a}+\\frac{1}{2}\\bs{b} \\right)\\cdot \\left( \\frac{2}{3}\\bs{a}+\\frac{1}{3}\\bs{b} \\right)=\\frac{1}{12}\\left( 2|\\bs{a}|^2+5\\bs{a}\\cdot\\bs{b}+2|\\bs{b}|^2 \\right)</span>. 设 <span class=\"gk-math\" data-tex=\"AB=x\">AB=x</span>，<span class=\"gk-math\" data-tex=\"AC=y\">AC=y</span>，则 <span class=\"gk-math\" data-tex=\"\\bs{a}\\cdot\\bs{b}=xy\\cos 60^\\circ=\\frac{xy}{2}\">\\bs{a}\\cdot\\bs{b}=xy\\cos 60^\\circ=\\frac{xy}{2}</span>，故 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AE}\\cdot \\overrightarrow{AF}=\\frac{1}{12}\\left( 2x^2+\\frac{5xy}{2}+2y^2 \\right)\">\\overrightarrow{AE}\\cdot \\overrightarrow{AF}=\\frac{1}{12}\\left( 2x^2+\\frac{5xy}{2}+2y^2 \\right)</span>. 又由余弦定理， <span class=\"gk-math\" data-tex=\"BC^2=x^2+y^2-2xy\\cos 60^\\circ=x^2+y^2-xy=1\">BC^2=x^2+y^2-2xy\\cos 60^\\circ=x^2+y^2-xy=1</span>. 所以 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AE}\\cdot \\overrightarrow{AF}=\\frac{1}{12}\\left( 2xy+\\frac{5xy}{2}+2 \\right)=\\frac{1}{12}\\left( \\frac{9xy}{2}+2 \\right)\">\\overrightarrow{AE}\\cdot \\overrightarrow{AF}=\\frac{1}{12}\\left( 2xy+\\frac{5xy}{2}+2 \\right)=\\frac{1}{12}\\left( \\frac{9xy}{2}+2 \\right)</span>. 由 <span class=\"gk-math\" data-tex=\"x^2+y^2-xy=1\\ge xy\">x^2+y^2-xy=1\\ge xy</span> 得 <span class=\"gk-math\" data-tex=\"xy\\le 1\">xy\\le 1</span>，当且仅当 <span class=\"gk-math\" data-tex=\"x=y=1\">x=y=1</span> 时取等号. 故最大值为 <span class=\"gk-math\" data-tex=\"\\frac{1}{12}\\left( \\frac{9}{2}+2 \\right)=\\frac{13}{24}\">\\frac{1}{12}\\left( \\frac{9}{2}+2 \\right)=\\frac{13}{24}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q15","paperId":"2023-tianjin","number":15,"type":"fill","score":5,"lessonIds":["3.4","2.3"],"difficulty":"挑战","hint":"先按绝对值里是正还是负分成两段，每段方程都能因式分解。解出来还要代回该段条件。","legacy":false,"legacyReason":"","searchText":"若函数 f(x)=ax^2-2x-\\left| x^2-ax+1 \\right| 有且仅有两个零点，则 a 的取值范围为 ________ . ","questionHtml":"若函数 <span class=\"gk-math\" data-tex=\"f(x)=ax^2-2x-\\left| x^2-ax+1 \\right|\">f(x)=ax^2-2x-\\left| x^2-ax+1 \\right|</span> 有且仅有两个零点，则 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"(-\\infty,0)\\cup (0,1)\\cup (1,+\\infty)\">(-\\infty,0)\\cup (0,1)\\cup (1,+\\infty)</span>","answerKey":"","solutionHtml":"分两种情况讨论.<br><br>当 <span class=\"gk-math\" data-tex=\"x^2-ax+1\\ge 0\">x^2-ax+1\\ge 0</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=0\\Longleftrightarrow (a-1)x^2+(a-2)x-1=0\\Longleftrightarrow \\bigl[(a-1)x-1\\bigr](x+1)=0\">f(x)=0\\Longleftrightarrow (a-1)x^2+(a-2)x-1=0\\Longleftrightarrow \\bigl[(a-1)x-1\\bigr](x+1)=0</span>.<br><br>若 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span>，则方程只有根 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span>，且 <span class=\"gk-math\" data-tex=\"(-1)^2-a(-1)+1=3\\ge 0\">(-1)^2-a(-1)+1=3\\ge 0</span>.<br><br>若 <span class=\"gk-math\" data-tex=\"a\\ne 1\">a\\ne 1</span>，则方程根为 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span> 或 <span class=\"gk-math\" data-tex=\"x=\\dfrac{1}{a-1}\">x=\\dfrac{1}{a-1}</span>.<br><br>当根为 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span> 时，需满足 <span class=\"gk-math\" data-tex=\"(-1)^2-a(-1)+1\\ge 0\">(-1)^2-a(-1)+1\\ge 0</span>， 即 <span class=\"gk-math\" data-tex=\"a\\ge -2\">a\\ge -2</span>.<br><br>当根为 <span class=\"gk-math\" data-tex=\"x=\\dfrac{1}{a-1}\">x=\\dfrac{1}{a-1}</span> 时，需满足 <span class=\"gk-math\" data-tex=\"\\left( \\frac{1}{a-1} \\right)^2-a\\cdot \\frac{1}{a-1}+1\\ge 0\">\\left( \\frac{1}{a-1} \\right)^2-a\\cdot \\frac{1}{a-1}+1\\ge 0</span>， 解得 <span class=\"gk-math\" data-tex=\"a\\le 2\">a\\le 2</span> 且 <span class=\"gk-math\" data-tex=\"a\\ne 1\">a\\ne 1</span>.<br><br>当 <span class=\"gk-math\" data-tex=\"x^2-ax+1&lt;0\">x^2-ax+1&lt;0</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=0\\Longleftrightarrow (a+1)x^2-(a+2)x+1=0\\Longleftrightarrow \\bigl[(a+1)x-1\\bigr](x-1)=0\">f(x)=0\\Longleftrightarrow (a+1)x^2-(a+2)x+1=0\\Longleftrightarrow \\bigl[(a+1)x-1\\bigr](x-1)=0</span>.<br><br>若 <span class=\"gk-math\" data-tex=\"a=-1\">a=-1</span>，则方程只有根 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span>，但 <span class=\"gk-math\" data-tex=\"1-a+1=3&gt;0\">1-a+1=3&gt;0</span>， 不满足 <span class=\"gk-math\" data-tex=\"x^2-ax+1&lt;0\">x^2-ax+1&lt;0</span>.<br><br>若 <span class=\"gk-math\" data-tex=\"a\\ne -1\">a\\ne -1</span>，则方程根为 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 或 <span class=\"gk-math\" data-tex=\"x=\\dfrac{1}{a+1}\">x=\\dfrac{1}{a+1}</span>.<br><br>当根为 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 时，需满足 <span class=\"gk-math\" data-tex=\"1-a+1&lt;0\">1-a+1&lt;0</span>， 即 <span class=\"gk-math\" data-tex=\"a&gt;2\">a&gt;2</span>.<br><br>当根为 <span class=\"gk-math\" data-tex=\"x=\\dfrac{1}{a+1}\">x=\\dfrac{1}{a+1}</span> 时，需满足 <span class=\"gk-math\" data-tex=\"\\left( \\frac{1}{a+1} \\right)^2-a\\cdot \\frac{1}{a+1}+1&lt;0\">\\left( \\frac{1}{a+1} \\right)^2-a\\cdot \\frac{1}{a+1}+1&lt;0</span>， 解得 <span class=\"gk-math\" data-tex=\"a&lt;-2\">a&lt;-2</span>.<br><br>综上：当 <span class=\"gk-math\" data-tex=\"a&lt;-2\">a&lt;-2</span> 时，零点为 <span class=\"gk-math\" data-tex=\"\\frac{1}{a-1}\">\\frac{1}{a-1}</span>，<span class=\"gk-math\" data-tex=\"\\frac{1}{a+1}\">\\frac{1}{a+1}</span>；当 <span class=\"gk-math\" data-tex=\"-2\\le a&lt;0\">-2\\le a&lt;0</span> 时，零点为 <span class=\"gk-math\" data-tex=\"\\frac{1}{a-1}\">\\frac{1}{a-1}</span>，<span class=\"gk-math\" data-tex=\"-1\">-1</span>；当 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 时，只有一个零点 <span class=\"gk-math\" data-tex=\"-1\">-1</span>；当 <span class=\"gk-math\" data-tex=\"0&lt;a&lt;1\">0&lt;a&lt;1</span> 时，零点为 <span class=\"gk-math\" data-tex=\"\\frac{1}{a-1}\">\\frac{1}{a-1}</span>，<span class=\"gk-math\" data-tex=\"-1\">-1</span>；当 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span> 时，只有一个零点 <span class=\"gk-math\" data-tex=\"-1\">-1</span>；当 <span class=\"gk-math\" data-tex=\"1&lt;a\\le 2\">1&lt;a\\le 2</span> 时，零点为 <span class=\"gk-math\" data-tex=\"\\frac{1}{a-1}\">\\frac{1}{a-1}</span>，<span class=\"gk-math\" data-tex=\"-1\">-1</span>；当 <span class=\"gk-math\" data-tex=\"a&gt;2\">a&gt;2</span> 时，零点为 <span class=\"gk-math\" data-tex=\"-1,1\">-1,1</span>.<br><br>故 <span class=\"gk-math\" data-tex=\"a\\in (-\\infty,0)\\cup (0,1)\\cup (1,+\\infty)\">a\\in (-\\infty,0)\\cup (0,1)\\cup (1,+\\infty)</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q16","paperId":"2023-tianjin","number":16,"type":"written","score":14,"lessonIds":["6.4","5.5"],"difficulty":"进阶","hint":"第一问直接用正弦定理；求c时用余弦定理，得到的负边长记得舍去。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中，角 A ， B ， C 所对的边分别是 a ， b ， c . 已知 a=\\sqrt{39} ， b=2 ， \\angle A=120^\\circ . 求 \\sin B 的值； 求 c 的值； 求 \\sin(B-C) . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，角 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 所对的边分别是 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span>. 已知 <span class=\"gk-math\" data-tex=\"a=\\sqrt{39}\">a=\\sqrt{39}</span>，<span class=\"gk-math\" data-tex=\"b=2\">b=2</span>，<span class=\"gk-math\" data-tex=\"\\angle A=120^\\circ\">\\angle A=120^\\circ</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"\\sin B\">\\sin B</span> 的值；</li><li>求 <span class=\"gk-math\" data-tex=\"c\">c</span> 的值；</li><li>求 <span class=\"gk-math\" data-tex=\"\\sin(B-C)\">\\sin(B-C)</span>.</li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{13}}{13}\">\\frac{\\sqrt{13}}{13}</span>；（2）<span class=\"gk-math\" data-tex=\"c=5\">c=5</span>；（3）<span class=\"gk-math\" data-tex=\"-\\frac{7\\sqrt3}{26}\">-\\frac{7\\sqrt3}{26}</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由正弦定理，<span class=\"gk-math\" data-tex=\"\\frac{a}{\\sin A}=\\frac{b}{\\sin B}\">\\frac{a}{\\sin A}=\\frac{b}{\\sin B}</span>，即 <span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{39}}{\\sin 120^\\circ}=\\frac{2}{\\sin B}\">\\frac{\\sqrt{39}}{\\sin 120^\\circ}=\\frac{2}{\\sin B}</span>. 解得 <span class=\"gk-math\" data-tex=\"\\sin B=\\frac{\\sqrt{13}}{13}\">\\sin B=\\frac{\\sqrt{13}}{13}</span>.</li><li>由余弦定理，<span class=\"gk-math\" data-tex=\"a^2=b^2+c^2-2bc\\cos A\">a^2=b^2+c^2-2bc\\cos A</span>. 代入已知得 <span class=\"gk-math\" data-tex=\"39=4+c^2-4c\\left( -\\frac{1}{2} \\right)\">39=4+c^2-4c\\left( -\\frac{1}{2} \\right)</span>，即 <span class=\"gk-math\" data-tex=\"c^2+2c-35=0\">c^2+2c-35=0</span>. 解得 <span class=\"gk-math\" data-tex=\"c=5\">c=5</span> 或 <span class=\"gk-math\" data-tex=\"c=-7\">c=-7</span>，舍去负值，故 <span class=\"gk-math\" data-tex=\"c=5\">c=5</span>.</li><li>由正弦定理，<span class=\"gk-math\" data-tex=\"\\frac{a}{\\sin A}=\\frac{c}{\\sin C}\">\\frac{a}{\\sin A}=\\frac{c}{\\sin C}</span>，得 <span class=\"gk-math\" data-tex=\"\\sin C=\\frac{5\\sqrt{13}}{26}\">\\sin C=\\frac{5\\sqrt{13}}{26}</span>. 又 <span class=\"gk-math\" data-tex=\"A=120^\\circ\">A=120^\\circ</span>，故 <span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 均为锐角，从而 <span class=\"gk-math\" data-tex=\"\\cos B=\\sqrt{1-\\sin^2 B}=\\frac{2\\sqrt{39}}{13}\">\\cos B=\\sqrt{1-\\sin^2 B}=\\frac{2\\sqrt{39}}{13}</span>，<span class=\"gk-math\" data-tex=\"\\cos C=\\sqrt{1-\\sin^2 C}=\\frac{3\\sqrt{39}}{26}\">\\cos C=\\sqrt{1-\\sin^2 C}=\\frac{3\\sqrt{39}}{26}</span>. 因此 <div class=\"gk-math display\" data-tex=\"\\sin(B-C)\n=\\sin B\\cos C-\\cos B\\sin C\n=\\frac{\\sqrt{13}}{13}\\cdot \\frac{3\\sqrt{39}}{26}-\\frac{2\\sqrt{39}}{13}\\cdot \\frac{5\\sqrt{13}}{26}\n=-\\frac{7\\sqrt3}{26}\">\\sin(B-C)\n=\\sin B\\cos C-\\cos B\\sin C\n=\\frac{\\sqrt{13}}{13}\\cdot \\frac{3\\sqrt{39}}{26}-\\frac{2\\sqrt{39}}{13}\\cdot \\frac{5\\sqrt{13}}{26}\n=-\\frac{7\\sqrt3}{26}</div></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q17","paperId":"2023-tianjin","number":17,"type":"written","score":15,"lessonIds":["8.5","e1-1.4"],"difficulty":"进阶","hint":"先利用两个中点找到平行四边形。求夹角和距离时，把A、AB、AC、AA₁当作坐标系来算。","legacy":false,"legacyReason":"","searchText":"三棱台 ABC-A_1B_1C_1 中，若 A_1A\\perp \\text{面 }ABC ， AB\\perp AC ， AB=AC=A_1A=2 ， A_1C_1=1 ， M ， N 分别是 BC ， BA 中点. 求证： A_1N\\parallel \\text{平面 }C_1MA ； 求平面 C_1MA 与平面 ACC_1A_1 所成夹角的余弦值； 求点 C 到平面 C_1MA 的距离. ","questionHtml":"三棱台 <span class=\"gk-math\" data-tex=\"ABC-A_1B_1C_1\">ABC-A_1B_1C_1</span> 中，若 <span class=\"gk-math\" data-tex=\"A_1A\\perp \\text{面 }ABC\">A_1A\\perp \\text{面 }ABC</span>，<span class=\"gk-math\" data-tex=\"AB\\perp AC\">AB\\perp AC</span>，<span class=\"gk-math\" data-tex=\"AB=AC=A_1A=2\">AB=AC=A_1A=2</span>，<span class=\"gk-math\" data-tex=\"A_1C_1=1\">A_1C_1=1</span>，<span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span> 分别是 <span class=\"gk-math\" data-tex=\"BC\">BC</span>，<span class=\"gk-math\" data-tex=\"BA\">BA</span> 中点.<br><br><ol class=\"gk-subparts\"><li>求证：<span class=\"gk-math\" data-tex=\"A_1N\\parallel \\text{平面 }C_1MA\">A_1N\\parallel \\text{平面 }C_1MA</span>；</li><li>求平面 <span class=\"gk-math\" data-tex=\"C_1MA\">C_1MA</span> 与平面 <span class=\"gk-math\" data-tex=\"ACC_1A_1\">ACC_1A_1</span> 所成夹角的余弦值；</li><li>求点 <span class=\"gk-math\" data-tex=\"C\">C</span> 到平面 <span class=\"gk-math\" data-tex=\"C_1MA\">C_1MA</span> 的距离.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,566px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q17_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q17_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"550\" height=\"544\" style=\"aspect-ratio:550/544;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"（1）证明见解析；（2）<span class=\"gk-math\" data-tex=\"\\frac23\">\\frac23</span>；（3）<span class=\"gk-math\" data-tex=\"\\frac43\">\\frac43</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>连接 <span class=\"gk-math\" data-tex=\"MN\">MN</span>，<span class=\"gk-math\" data-tex=\"C_1A\">C_1A</span>. 由 <span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span> 分别是 <span class=\"gk-math\" data-tex=\"BC\">BC</span>，<span class=\"gk-math\" data-tex=\"BA\">BA</span> 中点，得 <span class=\"gk-math\" data-tex=\"MN\\parallel AC\">MN\\parallel AC</span>，<span class=\"gk-math\" data-tex=\"MN=\\frac{AC}{2}=1\">MN=\\frac{AC}{2}=1</span>. 又由棱台性质， <span class=\"gk-math\" data-tex=\"A_1C_1\\parallel AC\">A_1C_1\\parallel AC</span>，<span class=\"gk-math\" data-tex=\"A_1C_1=1\">A_1C_1=1</span>. 故 <span class=\"gk-math\" data-tex=\"MN\\parallel A_1C_1\">MN\\parallel A_1C_1</span>，且 <span class=\"gk-math\" data-tex=\"MN=A_1C_1\">MN=A_1C_1</span>. 于是四边形 <span class=\"gk-math\" data-tex=\"MNA_1C_1\">MNA_1C_1</span> 为平行四边形，从而 <span class=\"gk-math\" data-tex=\"A_1N\\parallel MC_1\">A_1N\\parallel MC_1</span>. 因为 <span class=\"gk-math\" data-tex=\"MC_1\\subset \\text{平面 }C_1MA\">MC_1\\subset \\text{平面 }C_1MA</span>，且 <span class=\"gk-math\" data-tex=\"A_1N\\not\\subset \\text{平面 }C_1MA\">A_1N\\not\\subset \\text{平面 }C_1MA</span>，所以 <span class=\"gk-math\" data-tex=\"A_1N\\parallel \\text{平面 }C_1MA\">A_1N\\parallel \\text{平面 }C_1MA</span>. <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,431px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"415\" height=\"378\" style=\"aspect-ratio:415/378;width:100%\" loading=\"lazy\"></button></figure></li><li>过 <span class=\"gk-math\" data-tex=\"M\">M</span> 作 <span class=\"gk-math\" data-tex=\"ME\\perp AC\">ME\\perp AC</span>，垂足为 <span class=\"gk-math\" data-tex=\"E\">E</span>；过 <span class=\"gk-math\" data-tex=\"E\">E</span> 作 <span class=\"gk-math\" data-tex=\"EF\\perp AC_1\">EF\\perp AC_1</span>，垂足为 <span class=\"gk-math\" data-tex=\"F\">F</span>，连接 <span class=\"gk-math\" data-tex=\"MF\">MF</span>，<span class=\"gk-math\" data-tex=\"C_1E\">C_1E</span>. <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,429px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig2.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig2.webp\" alt=\"高考题图，点击可放大\" width=\"413\" height=\"378\" style=\"aspect-ratio:413/378;width:100%\" loading=\"lazy\"></button></figure> 因为 <span class=\"gk-math\" data-tex=\"A_1A\\perp \\text{面 }ABC\">A_1A\\perp \\text{面 }ABC</span>，且 <span class=\"gk-math\" data-tex=\"ME\\subset \\text{面 }ABC\">ME\\subset \\text{面 }ABC</span>，故 <span class=\"gk-math\" data-tex=\"A_1A\\perp ME\">A_1A\\perp ME</span>. 又 <span class=\"gk-math\" data-tex=\"ME\\perp AC\">ME\\perp AC</span>，<span class=\"gk-math\" data-tex=\"AC\\cap A_1A=A\">AC\\cap A_1A=A</span>，<span class=\"gk-math\" data-tex=\"AC\">AC</span>，<span class=\"gk-math\" data-tex=\"A_1A\\subset \\text{平面 }ACC_1A_1\">A_1A\\subset \\text{平面 }ACC_1A_1</span>，从而 <span class=\"gk-math\" data-tex=\"ME\\perp \\text{平面 }ACC_1A_1\">ME\\perp \\text{平面 }ACC_1A_1</span>. 又 <span class=\"gk-math\" data-tex=\"AC_1\\subset \\text{平面 }ACC_1A_1\">AC_1\\subset \\text{平面 }ACC_1A_1</span>，故 <span class=\"gk-math\" data-tex=\"ME\\perp AC_1\">ME\\perp AC_1</span>. 又 <span class=\"gk-math\" data-tex=\"EF\\perp AC_1\">EF\\perp AC_1</span>，<span class=\"gk-math\" data-tex=\"ME\\cap EF=E\">ME\\cap EF=E</span>，<span class=\"gk-math\" data-tex=\"ME\">ME</span>，<span class=\"gk-math\" data-tex=\"EF\\subset \\text{平面 }MEF\">EF\\subset \\text{平面 }MEF</span>，于是 <span class=\"gk-math\" data-tex=\"AC_1\\perp \\text{平面 }MEF\">AC_1\\perp \\text{平面 }MEF</span>. 由 <span class=\"gk-math\" data-tex=\"MF\\subset \\text{平面 }MEF\">MF\\subset \\text{平面 }MEF</span>，故 <span class=\"gk-math\" data-tex=\"AC_1\\perp MF\">AC_1\\perp MF</span>. 于是平面 <span class=\"gk-math\" data-tex=\"C_1MA\">C_1MA</span> 与平面 <span class=\"gk-math\" data-tex=\"ACC_1A_1\">ACC_1A_1</span> 所成角即 <span class=\"gk-math\" data-tex=\"\\angle MFE\">\\angle MFE</span>. 又 <span class=\"gk-math\" data-tex=\"ME=\\frac{AB}{2}=1\">ME=\\frac{AB}{2}=1</span>， 且 <span class=\"gk-math\" data-tex=\"\\cos \\angle CAC_1=\\frac{1}{\\sqrt5}\">\\cos \\angle CAC_1=\\frac{1}{\\sqrt5}</span>，<span class=\"gk-math\" data-tex=\"\\sin \\angle CAC_1=\\frac{2}{\\sqrt5}\">\\sin \\angle CAC_1=\\frac{2}{\\sqrt5}</span>. 故 <span class=\"gk-math\" data-tex=\"EF=ME\\sin \\angle CAC_1=\\frac{2}{\\sqrt5}\">EF=ME\\sin \\angle CAC_1=\\frac{2}{\\sqrt5}</span>. 在直角三角形 <span class=\"gk-math\" data-tex=\"MEF\">MEF</span> 中， <span class=\"gk-math\" data-tex=\"MF=\\sqrt{ME^2+EF^2}=\\sqrt{1+\\frac{4}{5}}=\\frac{3}{\\sqrt5}\">MF=\\sqrt{ME^2+EF^2}=\\sqrt{1+\\frac{4}{5}}=\\frac{3}{\\sqrt5}</span>. 于是 <span class=\"gk-math\" data-tex=\"\\cos \\angle MFE=\\frac{EF}{MF}=\\frac{2}{3}\">\\cos \\angle MFE=\\frac{EF}{MF}=\\frac{2}{3}</span>.</li><li>【法一】几何法<br><br>过 <span class=\"gk-math\" data-tex=\"C_1\">C_1</span> 作 <span class=\"gk-math\" data-tex=\"C_1P\\perp AC\">C_1P\\perp AC</span>，垂足为 <span class=\"gk-math\" data-tex=\"P\">P</span>，作 <span class=\"gk-math\" data-tex=\"C_1Q\\perp AM\">C_1Q\\perp AM</span>，垂足为 <span class=\"gk-math\" data-tex=\"Q\">Q</span>，连接 <span class=\"gk-math\" data-tex=\"PQ\">PQ</span>，<span class=\"gk-math\" data-tex=\"PM\">PM</span>，过 <span class=\"gk-math\" data-tex=\"P\">P</span> 作 <span class=\"gk-math\" data-tex=\"PR\\perp C_1Q\">PR\\perp C_1Q</span>，垂足为 <span class=\"gk-math\" data-tex=\"R\">R</span>. <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,390px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig3.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig3.webp\" alt=\"高考题图，点击可放大\" width=\"374\" height=\"343\" style=\"aspect-ratio:374/343;width:100%\" loading=\"lazy\"></button></figure> 由题干数据可得，<span class=\"gk-math\" data-tex=\"C_1A=C_1C=\\sqrt5\">C_1A=C_1C=\\sqrt5</span>，<span class=\"gk-math\" data-tex=\"C_1M=\\sqrt{C_1P^2+PM^2}=\\sqrt5\">C_1M=\\sqrt{C_1P^2+PM^2}=\\sqrt5</span>，根据勾股定理，<span class=\"gk-math\" data-tex=\"C_1Q=\\sqrt{5-\\left( \\frac{\\sqrt2}{2} \\right)^2}=\\frac{3\\sqrt2}{2}\">C_1Q=\\sqrt{5-\\left( \\frac{\\sqrt2}{2} \\right)^2}=\\frac{3\\sqrt2}{2}</span>. 由 <span class=\"gk-math\" data-tex=\"C_1P\\perp \\text{平面 }AMC\">C_1P\\perp \\text{平面 }AMC</span>，<span class=\"gk-math\" data-tex=\"AM\\subset \\text{平面 }AMC\">AM\\subset \\text{平面 }AMC</span>，则 <span class=\"gk-math\" data-tex=\"C_1P\\perp AM\">C_1P\\perp AM</span>，又 <span class=\"gk-math\" data-tex=\"C_1Q\\perp AM\">C_1Q\\perp AM</span>，<span class=\"gk-math\" data-tex=\"C_1Q\\cap C_1P=C_1\">C_1Q\\cap C_1P=C_1</span>，<span class=\"gk-math\" data-tex=\"C_1Q\">C_1Q</span>，<span class=\"gk-math\" data-tex=\"C_1P\\subset \\text{平面 }C_1PQ\">C_1P\\subset \\text{平面 }C_1PQ</span>，于是 <span class=\"gk-math\" data-tex=\"AM\\perp \\text{平面 }C_1PQ\">AM\\perp \\text{平面 }C_1PQ</span>. 又 <span class=\"gk-math\" data-tex=\"PR\\subset \\text{平面 }C_1PQ\">PR\\subset \\text{平面 }C_1PQ</span>，则 <span class=\"gk-math\" data-tex=\"PR\\perp AM\">PR\\perp AM</span>，又 <span class=\"gk-math\" data-tex=\"PR\\perp C_1Q\">PR\\perp C_1Q</span>，<span class=\"gk-math\" data-tex=\"C_1Q\\cap AM=Q\">C_1Q\\cap AM=Q</span>，<span class=\"gk-math\" data-tex=\"C_1Q\">C_1Q</span>，<span class=\"gk-math\" data-tex=\"AM\\subset \\text{平面 }C_1MA\">AM\\subset \\text{平面 }C_1MA</span>，故 <span class=\"gk-math\" data-tex=\"PR\\perp \\text{平面 }C_1MA\">PR\\perp \\text{平面 }C_1MA</span>. 在 <span class=\"gk-math\" data-tex=\"\\mathrm{Rt}\\triangle C_1PQ\">\\mathrm{Rt}\\triangle C_1PQ</span> 中，<span class=\"gk-math\" data-tex=\"PR=\\frac{PC_1\\cdot PQ}{QC_1}=\\frac{2\\cdot \\frac{\\sqrt2}{2}}{\\frac{3\\sqrt2}{2}}=\\frac{2}{3}\">PR=\\frac{PC_1\\cdot PQ}{QC_1}=\\frac{2\\cdot \\frac{\\sqrt2}{2}}{\\frac{3\\sqrt2}{2}}=\\frac{2}{3}</span>. 又 <span class=\"gk-math\" data-tex=\"CA=2PA\">CA=2PA</span>，故点 <span class=\"gk-math\" data-tex=\"C\">C</span> 到平面 <span class=\"gk-math\" data-tex=\"C_1MA\">C_1MA</span> 的距离是点 <span class=\"gk-math\" data-tex=\"P\">P</span> 到平面 <span class=\"gk-math\" data-tex=\"C_1MA\">C_1MA</span> 的距离的两倍，<span class=\"gk-math\" data-tex=\"d\\bigl(C,\\text{平面 }C_1MA\\bigr)=2PR=\\frac{4}{3}\">d\\bigl(C,\\text{平面 }C_1MA\\bigr)=2PR=\\frac{4}{3}</span>.<br><br>【法二】等体积法 <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,390px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig3.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q17_solution_fig3.webp\" alt=\"高考题图，点击可放大\" width=\"374\" height=\"343\" style=\"aspect-ratio:374/343;width:100%\" loading=\"lazy\"></button></figure> 辅助线同方法一. 设点 <span class=\"gk-math\" data-tex=\"C\">C</span> 到平面 <span class=\"gk-math\" data-tex=\"C_1MA\">C_1MA</span> 的距离为 <span class=\"gk-math\" data-tex=\"h\">h</span>. <span class=\"gk-math\" data-tex=\"V_{C_1-AMC}=\\frac{1}{3}\\times C_1P\\times S_{\\triangle AMC}=\\frac{1}{3}\\times 2\\times \\frac{1}{2}\\times \\left( \\sqrt2 \\right)^2=\\frac{2}{3}\">V_{C_1-AMC}=\\frac{1}{3}\\times C_1P\\times S_{\\triangle AMC}=\\frac{1}{3}\\times 2\\times \\frac{1}{2}\\times \\left( \\sqrt2 \\right)^2=\\frac{2}{3}</span> <span class=\"gk-math\" data-tex=\"V_{C-C_1MA}=\\frac{1}{3}\\times h\\times S_{\\triangle AMC_1}=\\frac{1}{3}\\times h\\times \\frac{1}{2}\\times \\sqrt2\\times \\frac{3\\sqrt2}{2}=\\frac{h}{2}\">V_{C-C_1MA}=\\frac{1}{3}\\times h\\times S_{\\triangle AMC_1}=\\frac{1}{3}\\times h\\times \\frac{1}{2}\\times \\sqrt2\\times \\frac{3\\sqrt2}{2}=\\frac{h}{2}</span> 由 <span class=\"gk-math\" data-tex=\"V_{C_1-AMC}=V_{C-C_1MA}\">V_{C_1-AMC}=V_{C-C_1MA}</span>，得 <span class=\"gk-math\" data-tex=\"\\frac{h}{2}=\\frac{2}{3}\">\\frac{h}{2}=\\frac{2}{3}</span>， 即 <span class=\"gk-math\" data-tex=\"h=\\frac{4}{3}\">h=\\frac{4}{3}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q18","paperId":"2023-tianjin","number":18,"type":"written","score":15,"lessonIds":["e1-3.1","e1-2.2"],"difficulty":"进阶","hint":"a+c=3、a−c=1先解出a和c。第二问把A₂P设成y=k(x−2)，面积比例可转成坐标关系。","legacy":false,"legacyReason":"","searchText":"设椭圆 \\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1 （ a>b>0 ） 的左，右顶点分别为 A_1 ， A_2 ，右焦点为 F ，已知 |A_1F|=3 ， |A_2F|=1 . 求椭圆方程及其离心率； 已知点 P 是椭圆上一动点（不与端点重合），直线 A_2P 交 y 轴于点 Q ，若三角形 A_1PQ 的面积是三角形 A_2FP 面积的二倍，求直线 A_2P 的方程. ","questionHtml":"设椭圆 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1\">\\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>） 的左，右顶点分别为 <span class=\"gk-math\" data-tex=\"A_1\">A_1</span>，<span class=\"gk-math\" data-tex=\"A_2\">A_2</span>，右焦点为 <span class=\"gk-math\" data-tex=\"F\">F</span>，已知 <span class=\"gk-math\" data-tex=\"|A_1F|=3\">|A_1F|=3</span>，<span class=\"gk-math\" data-tex=\"|A_2F|=1\">|A_2F|=1</span>.<br><br><ol class=\"gk-subparts\"><li>求椭圆方程及其离心率；</li><li>已知点 <span class=\"gk-math\" data-tex=\"P\">P</span> 是椭圆上一动点（不与端点重合），直线 <span class=\"gk-math\" data-tex=\"A_2P\">A_2P</span> 交 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴于点 <span class=\"gk-math\" data-tex=\"Q\">Q</span>，若三角形 <span class=\"gk-math\" data-tex=\"A_1PQ\">A_1PQ</span> 的面积是三角形 <span class=\"gk-math\" data-tex=\"A_2FP\">A_2FP</span> 面积的二倍，求直线 <span class=\"gk-math\" data-tex=\"A_2P\">A_2P</span> 的方程.</li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"\\frac{x^2}4+\\frac{y^2}3=1\">\\frac{x^2}4+\\frac{y^2}3=1</span>，<span class=\"gk-math\" data-tex=\"e=\\frac12\">e=\\frac12</span>；（2）<span class=\"gk-math\" data-tex=\"y=\\pm\\frac{\\sqrt6}2(x-2)\">y=\\pm\\frac{\\sqrt6}2(x-2)</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"|A_1F|=a+c=3\">|A_1F|=a+c=3</span>，<span class=\"gk-math\" data-tex=\"|A_2F|=a-c=1\">|A_2F|=a-c=1</span> 解得 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span>，<span class=\"gk-math\" data-tex=\"c=1\">c=1</span>. 故 <span class=\"gk-math\" data-tex=\"b=\\sqrt{a^2-c^2}=\\sqrt{4-1}=\\sqrt3\">b=\\sqrt{a^2-c^2}=\\sqrt{4-1}=\\sqrt3</span>. 所以 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{4}+\\frac{y^2}{3}=1\">\\frac{x^2}{4}+\\frac{y^2}{3}=1</span>，<span class=\"gk-math\" data-tex=\"e=\\frac{c}{a}=\\frac{1}{2}\">e=\\frac{c}{a}=\\frac{1}{2}</span>.</li><li>由（1）知 <span class=\"gk-math\" data-tex=\"A_2(2,0)\">A_2(2,0)</span>. 设直线 <span class=\"gk-math\" data-tex=\"A_2P\">A_2P</span> 方程为 <span class=\"gk-math\" data-tex=\"y=k(x-2)\">y=k(x-2)</span>. 与椭圆联立 <div class=\"gk-math display\" data-tex=\"\\begin{cases}\n\\dfrac{x^2}{4}+\\dfrac{y^2}{3}=1,\\\\\ny=k(x-2).\n\\end{cases}\">\\begin{cases}\n\\dfrac{x^2}{4}+\\dfrac{y^2}{3}=1,\\\\\ny=k(x-2).\n\\end{cases}</div> 消去 <span class=\"gk-math\" data-tex=\"y\">y</span> 得 <span class=\"gk-math\" data-tex=\"(3+4k^2)x^2-16k^2x+16k^2-12=0\">(3+4k^2)x^2-16k^2x+16k^2-12=0</span>. 由韦达定理并利用 <span class=\"gk-math\" data-tex=\"x_{A_2}=2\">x_{A_2}=2</span> 可得 <span class=\"gk-math\" data-tex=\"x_P=\\frac{8k^2-6}{3+4k^2}\">x_P=\\frac{8k^2-6}{3+4k^2}</span>，<span class=\"gk-math\" data-tex=\"y_P=-\\frac{12k}{3+4k^2}\">y_P=-\\frac{12k}{3+4k^2}</span>，<span class=\"gk-math\" data-tex=\"Q(0,-2k)\">Q(0,-2k)</span>. <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,435px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/tianjin/q18_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/tianjin/q18_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"419\" height=\"442\" style=\"aspect-ratio:419/442;width:100%\" loading=\"lazy\"></button></figure> 面积条件给出 <span class=\"gk-math\" data-tex=\"S_{\\triangle A_2QA_1}=S_{\\triangle A_1PQ}+S_{\\triangle A_1A_2P}=2S_{\\triangle A_2FP}+S_{\\triangle A_1A_2P}\">S_{\\triangle A_2QA_1}=S_{\\triangle A_1PQ}+S_{\\triangle A_1A_2P}=2S_{\\triangle A_2FP}+S_{\\triangle A_1A_2P}</span>，化简为 <span class=\"gk-math\" data-tex=\"2|y_Q|=3|y_P|\">2|y_Q|=3|y_P|</span>. 即 <span class=\"gk-math\" data-tex=\"4|k|=3\\left| \\frac{12k}{3+4k^2} \\right|\">4|k|=3\\left| \\frac{12k}{3+4k^2} \\right|</span>. 解得 <span class=\"gk-math\" data-tex=\"k=\\pm \\frac{\\sqrt6}{2}\">k=\\pm \\frac{\\sqrt6}{2}</span>. 故直线 <span class=\"gk-math\" data-tex=\"A_2P\">A_2P</span> 的方程为 <span class=\"gk-math\" data-tex=\"y=\\pm \\frac{\\sqrt6}{2}(x-2)\">y=\\pm \\frac{\\sqrt6}{2}(x-2)</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q19","paperId":"2023-tianjin","number":19,"type":"written","score":15,"lessonIds":["e2-4.2","e2-4.3"],"difficulty":"挑战","hint":"先由a₅−a₃求公差。第二问每一段只需先看最小、最大的下标，再把bₖ夹在两个数之间。","legacy":false,"legacyReason":"","searchText":"已知 \\{a_n\\} 是等差数列， a_2+a_5=16 ， a_5-a_3=4 . 求 \\{a_n\\} 的通项公式和 \\displaystyle\\sum_{i=2^{n-1}}^{2^n-1}a_i ； 已知 \\{b_n\\} 为等比数列，对于任意 k\\in \\N^* ，若 2^{k-1}\\le n\\le 2^k-1 ，则 b_k<a_n<b_{k+1} . 当 k\\ge 2 时，求证： 2^k-1<b_k<2^k+1 ； 求 \\{b_n\\} 的通项公式及其前 n 项和. ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 是等差数列，<span class=\"gk-math\" data-tex=\"a_2+a_5=16\">a_2+a_5=16</span>，<span class=\"gk-math\" data-tex=\"a_5-a_3=4\">a_5-a_3=4</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的通项公式和 <span class=\"gk-math\" data-tex=\"\\displaystyle\\sum_{i=2^{n-1}}^{2^n-1}a_i\">\\displaystyle\\sum_{i=2^{n-1}}^{2^n-1}a_i</span>；</li><li>已知 <span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span> 为等比数列，对于任意 <span class=\"gk-math\" data-tex=\"k\\in \\N^*\">k\\in \\N^*</span>，若 <span class=\"gk-math\" data-tex=\"2^{k-1}\\le n\\le 2^k-1\">2^{k-1}\\le n\\le 2^k-1</span>，则 <span class=\"gk-math\" data-tex=\"b_k&lt;a_n&lt;b_{k+1}\">b_k&lt;a_n&lt;b_{k+1}</span>.<br><br><ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"k\\ge 2\">k\\ge 2</span> 时，求证：<span class=\"gk-math\" data-tex=\"2^k-1&lt;b_k&lt;2^k+1\">2^k-1&lt;b_k&lt;2^k+1</span>；</li><li>求 <span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span> 的通项公式及其前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和.</li></ol></li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"a_n=2n+1\">a_n=2n+1</span>，所求和为<span class=\"gk-math\" data-tex=\"3\\cdot4^{n-1}\">3\\cdot4^{n-1}</span>；（2）①证明见解析；②<span class=\"gk-math\" data-tex=\"b_n=2^n\">b_n=2^n</span>，前n项和为<span class=\"gk-math\" data-tex=\"2^{n+1}-2\">2^{n+1}-2</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>设等差数列首项为 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，公差为 <span class=\"gk-math\" data-tex=\"d\">d</span>. 由题意 <span class=\"gk-math\" data-tex=\"\\begin{cases}\na_2+a_5=2a_1+5d=16,\\\\\na_5-a_3=2d=4,\n\\end{cases}\">\\begin{cases}\na_2+a_5=2a_1+5d=16,\\\\\na_5-a_3=2d=4,\n\\end{cases}</span> 解得 <span class=\"gk-math\" data-tex=\"a_1=3\">a_1=3</span>，<span class=\"gk-math\" data-tex=\"d=2\">d=2</span>. 故 <span class=\"gk-math\" data-tex=\"a_n=a_1+(n-1)d=2n+1\">a_n=a_1+(n-1)d=2n+1</span>. 于是 <span class=\"gk-math\" data-tex=\"\\sum_{i=2^{n-1}}^{2^n-1}a_i=\\sum_{i=2^{n-1}}^{2^n-1}(2i+1)=3\\cdot 4^{n-1}\">\\sum_{i=2^{n-1}}^{2^n-1}a_i=\\sum_{i=2^{n-1}}^{2^n-1}(2i+1)=3\\cdot 4^{n-1}</span>.</li><li><ol class=\"gk-subparts\"><li>因为当 <span class=\"gk-math\" data-tex=\"2^{k-1}\\le n\\le 2^k-1\">2^{k-1}\\le n\\le 2^k-1</span> 时， <span class=\"gk-math\" data-tex=\"b_k&lt;a_n\">b_k&lt;a_n</span>， 取 <span class=\"gk-math\" data-tex=\"n=2^{k-1}\">n=2^{k-1}</span>，得 <span class=\"gk-math\" data-tex=\"b_k&lt;a_{2^{k-1}}=2^k+1\">b_k&lt;a_{2^{k-1}}=2^k+1</span>. 又当 <span class=\"gk-math\" data-tex=\"2^{k-2}\\le n\\le 2^{k-1}-1\">2^{k-2}\\le n\\le 2^{k-1}-1</span> 时， <span class=\"gk-math\" data-tex=\"a_n&lt;b_k\">a_n&lt;b_k</span>. 取 <span class=\"gk-math\" data-tex=\"n=2^{k-1}-1\">n=2^{k-1}-1</span>，得 <span class=\"gk-math\" data-tex=\"a_{2^{k-1}-1}=2^k-1&lt;b_k\">a_{2^{k-1}-1}=2^k-1&lt;b_k</span>. 故 <span class=\"gk-math\" data-tex=\"2^k-1&lt;b_k&lt;2^k+1\">2^k-1&lt;b_k&lt;2^k+1</span>.</li><li>由（1）可知 <span class=\"gk-math\" data-tex=\"2^k-1&lt;b_k&lt;2^k+1\">2^k-1&lt;b_k&lt;2^k+1</span>，<span class=\"gk-math\" data-tex=\"2^{k+1}-1&lt;b_{k+1}&lt;2^{k+1}+1\">2^{k+1}-1&lt;b_{k+1}&lt;2^{k+1}+1</span>. 则数列 <span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span> 的公比 <span class=\"gk-math\" data-tex=\"q\">q</span> 满足 <div class=\"gk-math display\" data-tex=\"\\frac{2^{k+1}-1}{2^k+1}\n=2-\\frac{3}{2^k+1}\n&lt;q\n=\\frac{b_{k+1}}{b_k}\n&lt;\\frac{2^{k+1}+1}{2^k-1}\n=2+\\frac{3}{2^k-1}\">\\frac{2^{k+1}-1}{2^k+1}\n=2-\\frac{3}{2^k+1}\n&lt;q\n=\\frac{b_{k+1}}{b_k}\n&lt;\\frac{2^{k+1}+1}{2^k-1}\n=2+\\frac{3}{2^k-1}</div> 当 <span class=\"gk-math\" data-tex=\"k\\in \\N^*\">k\\in \\N^*</span>，<span class=\"gk-math\" data-tex=\"k\\to +\\infty\">k\\to +\\infty</span> 时， <span class=\"gk-math\" data-tex=\"2-\\frac{3}{2^k+1}\\to 2\">2-\\frac{3}{2^k+1}\\to 2</span>，<span class=\"gk-math\" data-tex=\"2+\\frac{3}{2^k-1}\\to 2\">2+\\frac{3}{2^k-1}\\to 2</span>， 所以 <span class=\"gk-math\" data-tex=\"q=2\">q=2</span>. 所以 <span class=\"gk-math\" data-tex=\"2^k-1&lt;b_12^{k-1}&lt;2^k+1\">2^k-1&lt;b_12^{k-1}&lt;2^k+1</span>， 即 <span class=\"gk-math\" data-tex=\"2-\\frac{1}{2^{k-1}}&lt;b_1&lt;2+\\frac{1}{2^{k-1}}\">2-\\frac{1}{2^{k-1}}&lt;b_1&lt;2+\\frac{1}{2^{k-1}}</span>. 当 <span class=\"gk-math\" data-tex=\"k\\in \\N^*\">k\\in \\N^*</span>，<span class=\"gk-math\" data-tex=\"k\\to +\\infty\">k\\to +\\infty</span> 时， <span class=\"gk-math\" data-tex=\"2-\\frac{1}{2^{k-1}}\\to 2\">2-\\frac{1}{2^{k-1}}\\to 2</span>，<span class=\"gk-math\" data-tex=\"2+\\frac{1}{2^{k-1}}\\to 2\">2+\\frac{1}{2^{k-1}}\\to 2</span>， 所以 <span class=\"gk-math\" data-tex=\"b_1=2\">b_1=2</span>. 故 <span class=\"gk-math\" data-tex=\"b_n=2^n\">b_n=2^n</span>. 其前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和为 <span class=\"gk-math\" data-tex=\"S_n=\\frac{2(1-2^n)}{1-2}=2^{n+1}-2\">S_n=\\frac{2(1-2^n)}{1-2}=2^{n+1}-2</span>.</li></ol></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-tianjin-q20","paperId":"2023-tianjin","number":20,"type":"written","score":16,"lessonIds":["e2-5.1","e2-5.3","4.3"],"difficulty":"挑战","hint":"先对两个因子的乘积求导。证明f(x)>1时，可先研究ln(1+x)−2x/(x+2)的正负。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=\\left( \\frac{1}{x}+\\frac{1}{2} \\right)\\ln(x+1) . 求曲线 y=f(x) 在 x=2 处切线的斜率； 当 x>0 时，证明： f(x)>1 ； 证明： \\frac{5}{6}<\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n\\le 1\\quad(n\\in\\N^*) ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=\\left( \\frac{1}{x}+\\frac{1}{2} \\right)\\ln(x+1)\">f(x)=\\left( \\frac{1}{x}+\\frac{1}{2} \\right)\\ln(x+1)</span>.<br><br><ol class=\"gk-subparts\"><li>求曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 处切线的斜率；</li><li>当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时，证明：<span class=\"gk-math\" data-tex=\"f(x)&gt;1\">f(x)&gt;1</span>；</li><li>证明： <span class=\"gk-math\" data-tex=\"\\frac{5}{6}&lt;\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n\\le 1\\quad(n\\in\\N^*)\">\\frac{5}{6}&lt;\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n\\le 1\\quad(n\\in\\N^*)</span></li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"\\frac13-\\frac{\\ln3}4\">\\frac13-\\frac{\\ln3}4</span>；（2）（3）证明见解析.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"f(x)=\\frac{\\ln(x+1)}{x}+\\frac{1}{2}\\ln(x+1)\">f(x)=\\frac{\\ln(x+1)}{x}+\\frac{1}{2}\\ln(x+1)</span>， 得 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\frac{1}{x(x+1)}+\\frac{1}{2(x+1)}-\\frac{\\ln(x+1)}{x^2}\">f&#x27;(x)=\\frac{1}{x(x+1)}+\\frac{1}{2(x+1)}-\\frac{\\ln(x+1)}{x^2}</span>. 故 <span class=\"gk-math\" data-tex=\"f&#x27;(2)=\\frac{1}{6}+\\frac{1}{6}-\\frac{\\ln 3}{4}=\\frac{1}{3}-\\frac{\\ln 3}{4}\">f&#x27;(2)=\\frac{1}{6}+\\frac{1}{6}-\\frac{\\ln 3}{4}=\\frac{1}{3}-\\frac{\\ln 3}{4}</span>.</li><li>令 <span class=\"gk-math\" data-tex=\"g(x)=\\ln(x+1)-\\frac{2x}{x+2}\">g(x)=\\ln(x+1)-\\frac{2x}{x+2}</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>）. 则 <span class=\"gk-math\" data-tex=\"g&#x27;(x)=\\frac{1}{x+1}-\\frac{4}{(x+2)^2}=\\frac{x^2}{(x+1)(x+2)^2}&gt;0\">g&#x27;(x)=\\frac{1}{x+1}-\\frac{4}{(x+2)^2}=\\frac{x^2}{(x+1)(x+2)^2}&gt;0</span>. 故 <span class=\"gk-math\" data-tex=\"g(x)\">g(x)</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上递增. 又 <span class=\"gk-math\" data-tex=\"g(0)=0\">g(0)=0</span>， 所以当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时， <span class=\"gk-math\" data-tex=\"g(x)&gt;0\">g(x)&gt;0</span>， 即 <span class=\"gk-math\" data-tex=\"\\ln(x+1)&gt;\\frac{2x}{x+2}\">\\ln(x+1)&gt;\\frac{2x}{x+2}</span>. 两边乘以 <span class=\"gk-math\" data-tex=\"\\dfrac{1}{x}+\\dfrac{1}{2}=\\dfrac{x+2}{2x}&gt;0\">\\dfrac{1}{x}+\\dfrac{1}{2}=\\dfrac{x+2}{2x}&gt;0</span>，得 <span class=\"gk-math\" data-tex=\"f(x)=\\left( \\frac{1}{x}+\\frac{1}{2} \\right)\\ln(x+1)&gt;1\">f(x)=\\left( \\frac{1}{x}+\\frac{1}{2} \\right)\\ln(x+1)&gt;1</span>.</li><li>设 <span class=\"gk-math\" data-tex=\"h(n)=\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n\">h(n)=\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n</span>. 则 <span class=\"gk-math\" data-tex=\"h(n+1)-h(n)=1-\\left( n+\\frac{1}{2} \\right)\\ln\\left( 1+\\frac{1}{n} \\right)\">h(n+1)-h(n)=1-\\left( n+\\frac{1}{2} \\right)\\ln\\left( 1+\\frac{1}{n} \\right)</span>. 由（2）知：<span class=\"gk-math\" data-tex=\"x=\\dfrac{1}{n}\\in (0,1]\">x=\\dfrac{1}{n}\\in (0,1]</span>，则 <span class=\"gk-math\" data-tex=\"f\\left( \\frac{1}{n} \\right)=\\left( n+\\frac{1}{2} \\right)\\ln\\left( 1+\\frac{1}{n} \\right)&gt;1\">f\\left( \\frac{1}{n} \\right)=\\left( n+\\frac{1}{2} \\right)\\ln\\left( 1+\\frac{1}{n} \\right)&gt;1</span>， 故 <span class=\"gk-math\" data-tex=\"h(n+1)-h(n)&lt;0\">h(n+1)-h(n)&lt;0</span>. 故 <span class=\"gk-math\" data-tex=\"h(n)\">h(n)</span> 在 <span class=\"gk-math\" data-tex=\"n\\in \\N^*\">n\\in \\N^*</span> 上递减，而 <span class=\"gk-math\" data-tex=\"h(1)=1\">h(1)=1</span>， 故 <span class=\"gk-math\" data-tex=\"h(n)\\le 1\">h(n)\\le 1</span>.<br><br>下证 <span class=\"gk-math\" data-tex=\"\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n&gt;\\frac{5}{6}\">\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n&gt;\\frac{5}{6}</span>. 令 <span class=\"gk-math\" data-tex=\"\\varphi(x)=\\ln x-\\frac{(x+5)(x-1)}{4x+2}\">\\varphi(x)=\\ln x-\\frac{(x+5)(x-1)}{4x+2}</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>）. 则 <span class=\"gk-math\" data-tex=\"\\varphi&#x27;(x)=\\frac{(x-1)^2(1-x)}{x(2x+1)^2}\">\\varphi&#x27;(x)=\\frac{(x-1)^2(1-x)}{x(2x+1)^2}</span>. 当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;1\">0&lt;x&lt;1</span> 时 <span class=\"gk-math\" data-tex=\"\\varphi&#x27;(x)&gt;0\">\\varphi&#x27;(x)&gt;0</span>，<span class=\"gk-math\" data-tex=\"\\varphi(x)\">\\varphi(x)</span> 递增，当 <span class=\"gk-math\" data-tex=\"x&gt;1\">x&gt;1</span> 时 <span class=\"gk-math\" data-tex=\"\\varphi&#x27;(x)&lt;0\">\\varphi&#x27;(x)&lt;0</span>，<span class=\"gk-math\" data-tex=\"\\varphi(x)\">\\varphi(x)</span> 递减， 所以 <span class=\"gk-math\" data-tex=\"\\varphi(x)\\le \\varphi(1)=0\">\\varphi(x)\\le \\varphi(1)=0</span>，故在 <span class=\"gk-math\" data-tex=\"x\\in (0,+\\infty)\">x\\in (0,+\\infty)</span> 上 <span class=\"gk-math\" data-tex=\"\\ln x\\le \\frac{(x+5)(x-1)}{4x+2}\">\\ln x\\le \\frac{(x+5)(x-1)}{4x+2}</span> 恒成立， <div class=\"gk-math display\" data-tex=\"\\begin{aligned}\nh(n)-h(n+1)\n&amp;=\\left( n+\\frac{1}{2} \\right)\\ln\\left( 1+\\frac{1}{n} \\right)-1 \\\\\n&amp;\\le \\left( n+\\frac{1}{2} \\right)\\cdot \\frac{\\left( 6+\\frac{1}{n} \\right)\\frac{1}{n}}{2\\left( 3+\\frac{2}{n} \\right)}-1 \\\\\n&amp;=\\frac{1}{4n(3n+2)} &lt;\\frac{1}{12}\\left( \\frac{1}{n-1}-\\frac{1}{n} \\right)\n\\end{aligned}\">\\begin{aligned}\nh(n)-h(n+1)\n&amp;=\\left( n+\\frac{1}{2} \\right)\\ln\\left( 1+\\frac{1}{n} \\right)-1 \\\\\n&amp;\\le \\left( n+\\frac{1}{2} \\right)\\cdot \\frac{\\left( 6+\\frac{1}{n} \\right)\\frac{1}{n}}{2\\left( 3+\\frac{2}{n} \\right)}-1 \\\\\n&amp;=\\frac{1}{4n(3n+2)} &lt;\\frac{1}{12}\\left( \\frac{1}{n-1}-\\frac{1}{n} \\right)\n\\end{aligned}</div> 所以 <span class=\"gk-math\" data-tex=\"h(2)-h(3)&lt;\\frac{1}{12}\\left( 1-\\frac{1}{2} \\right)\">h(2)-h(3)&lt;\\frac{1}{12}\\left( 1-\\frac{1}{2} \\right)</span>，<span class=\"gk-math\" data-tex=\"h(3)-h(4)&lt;\\frac{1}{12}\\left( \\frac{1}{2}-\\frac{1}{3} \\right)\">h(3)-h(4)&lt;\\frac{1}{12}\\left( \\frac{1}{2}-\\frac{1}{3} \\right)</span>，<span class=\"gk-math\" data-tex=\"\\cdots\">\\cdots</span>，<span class=\"gk-math\" data-tex=\"h(n-1)-h(n)&lt;\\frac{1}{12}\\left( \\frac{1}{n-2}-\\frac{1}{n-1} \\right)\">h(n-1)-h(n)&lt;\\frac{1}{12}\\left( \\frac{1}{n-2}-\\frac{1}{n-1} \\right)</span>. 累加得： <span class=\"gk-math\" data-tex=\"h(2)-h(n)&lt;\\frac{1}{12}\\left( 1-\\frac{1}{n-1} \\right)\">h(2)-h(n)&lt;\\frac{1}{12}\\left( 1-\\frac{1}{n-1} \\right)</span>， 而 <span class=\"gk-math\" data-tex=\"h(2)=2-\\frac{3}{2}\\ln 2\">h(2)=2-\\frac{3}{2}\\ln 2</span>，<span class=\"gk-math\" data-tex=\"h(1)=1\">h(1)=1</span>. 因为 <span class=\"gk-math\" data-tex=\"\\frac{7}{9}&gt;\\frac{3}{4}&gt;\\ln 2\">\\frac{7}{9}&gt;\\frac{3}{4}&gt;\\ln 2</span>， 所以 <span class=\"gk-math\" data-tex=\"h(2)=2-\\frac{3}{2}\\ln 2&gt;\\frac{5}{6}\">h(2)=2-\\frac{3}{2}\\ln 2&gt;\\frac{5}{6}</span>. 则 <span class=\"gk-math\" data-tex=\"-h(n)&lt;\\frac{1}{12}\\left( 1-\\frac{1}{n-1} \\right)-2+\\frac{3}{2}\\ln 2\">-h(n)&lt;\\frac{1}{12}\\left( 1-\\frac{1}{n-1} \\right)-2+\\frac{3}{2}\\ln 2</span>（<span class=\"gk-math\" data-tex=\"n\\ge 3\">n\\ge 3</span>）， 所以 <span class=\"gk-math\" data-tex=\"h(1)-h(n)&lt;\\frac{3}{2}\\ln 2-1+\\frac{1}{12}\\left( 1-\\frac{1}{n-1} \\right)&lt;\\frac{3}{2}\\ln 2-1+\\frac{1}{12}\\le\\frac{21}{20}-1+\\frac1{12}=\\frac2{15}&lt;\\frac16\">h(1)-h(n)&lt;\\frac{3}{2}\\ln 2-1+\\frac{1}{12}\\left( 1-\\frac{1}{n-1} \\right)&lt;\\frac{3}{2}\\ln 2-1+\\frac{1}{12}\\le\\frac{21}{20}-1+\\frac1{12}=\\frac2{15}&lt;\\frac16</span>. 故 <span class=\"gk-math\" data-tex=\"h(n)&gt;\\frac{5}{6}\">h(n)&gt;\\frac{5}{6}</span>（<span class=\"gk-math\" data-tex=\"n\\ge 3\">n\\ge 3</span>）. 综上， <span class=\"gk-math\" data-tex=\"\\frac{5}{6}&lt;h(n)\\le 1\">\\frac{5}{6}&lt;h(n)\\le 1</span>. 记 <span class=\"gk-math\" data-tex=\"u_n=\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n\">u_n=\\ln(n!)-\\left( n+\\frac{1}{2} \\right)\\ln n+n</span>，则 <span class=\"gk-math\" data-tex=\"u_n\\in \\left( \\frac{5}{6},1 \\right]\">u_n\\in \\left( \\frac{5}{6},1 \\right]</span>.</li></ol>","sourceNote":"按整理本补出正整数n的范围。","specialNote":"","answerAlternatives":[]}];
